import {readFileSync} from 'node:fs';
import {join} from 'node:path';
import {setLogger} from '../../shared/logger.js';
import {HAL_WS_SUBPROTOCOL, credentialFromSubprotocol, selectSubprotocol} from './subprotocol.js';

const TOKEN = 'super-secret-token';

const doc = (path: string): string => readFileSync(join(process.cwd(), path), 'utf8');

describe('the hal.v1 marker', () => {
  it('is the literal the protocol spec and the getting-started client print', () => {
    const printed = {
      spec: doc('specs/hal-engine-websocket-protocol/spec.md').includes(
        `Sec-WebSocket-Protocol: ${HAL_WS_SUBPROTOCOL}, <access-token>`
      ),
      client: doc('docs/getting-started.md').includes(`['${HAL_WS_SUBPROTOCOL}', token]`),
    };

    expect({marker: HAL_WS_SUBPROTOCOL, printed}).toEqual({marker: 'hal.v1', printed: {spec: true, client: true}});
  });
});

describe('selectSubprotocol', () => {
  // The deprecation warning's wording and its silence about the offer are asserted over a real handshake.
  beforeEach(() => {
    setLogger({debug: () => undefined, info: () => undefined, warn: () => undefined, error: () => undefined});
  });

  afterEach(() => {
    setLogger();
  });

  it('answers the marker when it is offered first, never the token beside it', () => {
    expect(selectSubprotocol(new Set([HAL_WS_SUBPROTOCOL, TOKEN]))).toBe(HAL_WS_SUBPROTOCOL);
  });

  it('answers the marker when it is offered after the token', () => {
    expect(selectSubprotocol(new Set([TOKEN, HAL_WS_SUBPROTOCOL]))).toBe(HAL_WS_SUBPROTOCOL);
  });

  it('echoes a bare-token offer, the deprecated shape, for one minor', () => {
    expect(selectSubprotocol(new Set([TOKEN]))).toBe(TOKEN);
  });

  it('answers nothing for an empty offer', () => {
    expect(selectSubprotocol(new Set())).toBe(false);
  });
});

describe('credentialFromSubprotocol', () => {
  it('reads the token from a marker-first offer', () => {
    expect(credentialFromSubprotocol(`${HAL_WS_SUBPROTOCOL}, ${TOKEN}`)).toBe(TOKEN);
  });

  it('reads the token from a token-first offer', () => {
    expect(credentialFromSubprotocol(`${TOKEN}, ${HAL_WS_SUBPROTOCOL}`)).toBe(TOKEN);
  });

  it('reads the first non-marker value when two are offered beside the marker', () => {
    expect(credentialFromSubprotocol(`${HAL_WS_SUBPROTOCOL}, first, second`)).toBe('first');
  });

  it('reads a bare token, the deprecated shape', () => {
    expect(credentialFromSubprotocol(TOKEN)).toBe(TOKEN);
  });

  it('reads nothing when only the marker is offered', () => {
    expect(credentialFromSubprotocol(HAL_WS_SUBPROTOCOL)).toBeUndefined();
  });

  it('reads nothing when no subprotocol header was sent', () => {
    expect(credentialFromSubprotocol(undefined)).toBeUndefined();
  });
});
#!/usr/bin/env node
// Emits the Lore test-command `list` shape: a single JSON array of
// {id, name, file} objects, one per test, and nothing else on stdout.
// Jest cannot resolve test names without executing them - there is no
// dry-run - so the suite is run once with --json written to a temp file and
// progress sent to stderr, keeping stdout pure.
// The id is "<repo-relative-file>::<full test name>" - stable across runs,
// and exactly what the run command's {selector} splits back apart.
import {execFileSync} from 'node:child_process';
import {readFileSync, rmSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {join, relative} from 'node:path';
import process from 'node:process';

const reportFile = join(tmpdir(), `hal-engine-jest-report-${process.pid}.json`);

try {
  execFileSync('npx', ['jest', '--json', `--outputFile=${reportFile}`], {
    cwd: process.cwd(),
    stdio: ['ignore', 'ignore', 'inherit'],
    // The suite runs as ESM; jest needs the flag in every spawn, not just npm test.
    env: {...process.env, NODE_OPTIONS: `${process.env.NODE_OPTIONS ?? ''} --experimental-vm-modules`.trim()},
  });
} catch {
  // A failing test still produces a full report, and listing must not depend
  // on the suite being green. An unreadable report below is the real failure.
}

let report;

try {
  report = JSON.parse(readFileSync(reportFile, 'utf8'));
} catch (error) {
  process.stderr.write(`jest produced no readable report at ${reportFile}: ${error.message}\n`);
  process.exit(1);
} finally {
  rmSync(reportFile, {force: true});
}

const tests = report.testResults.flatMap(suite => {
  const file = relative(process.cwd(), suite.name);

  return suite.assertionResults.map(assertion => ({
    id: `${file}::${assertion.fullName}`,
    name: assertion.fullName,
    file,
  }));
});

process.stdout.write(`${JSON.stringify(tests)}\n`);
import {copyFileSync, readFileSync, rmSync} from 'node:fs';
import {join} from 'node:path';
import {scriptRunner} from './helpers/script-runner.js';

// A citation's line is derived; its name is what the author meant. These drive the real script.

const fixtures = 'scripts/fixtures/anchor-names/specs/sample';
const {run} = scriptRunner(join(process.cwd(), 'scripts', 'check-spec-anchor-names.mjs'));

const spec = (name: string) => `${fixtures}/${name}.md`;

// --fix rewrites its input, so a case that repairs works on a copy and restores it afterwards.
const onACopy = (name: string, act: (path: string) => void): string => {
  const original = join(process.cwd(), spec(name));
  const backup = `${original}.backup`;
  copyFileSync(original, backup);
  try {
    act(spec(name));
    return readFileSync(original, 'utf8');
  } finally {
    copyFileSync(backup, original);
    rmSync(backup);
  }
};

describe('check-spec-anchor-names', () => {
  it('accepts a citation whose name matches the declaration it points at', () => {
    expect(run(spec('named'))).toMatchObject({status: 0});
  });

  it('reports a citation whose line has moved away from the test it names', () => {
    expect(run(spec('drifted'))).toMatchObject({status: 1});
  });

  it('names the line the cited test actually sits on, so the repair is obvious', () => {
    expect(run(spec('drifted')).stderr).toContain('points at #L2; it is at #L6');
  });

  it('reports a citation carrying no test name at all', () => {
    expect(run(spec('unnamed')).stderr).toContain('carries no test name');
  });

  it('reports a name no declaration in the cited file has', () => {
    expect(run(spec('absent')).stderr).toContain('which no declaration in');
  });

  it('repoints a drifted citation from the name it carries', () => {
    const after = onACopy('drifted', path => run(path, '--fix'));

    expect(after).toContain('#L6)');
  });

  it('fills in a missing name from the declaration the line points at', () => {
    const after = onACopy('unnamed', path => run(path, '--fix'));

    expect(after).toContain('[validated by: does the first thing]');
  });

  it('leaves a citation that already agrees with its declaration untouched', () => {
    const before = readFileSync(join(process.cwd(), spec('named')), 'utf8');
    const after = onACopy('named', path => run(path, '--fix'));

    expect(after).toBe(before);
  });

  it('reports a name that two declarations share, rather than choosing between them', () => {
    expect(run(spec('ambiguous')).stderr).toContain('names 2 declarations');
  });

  it('refuses to rewrite an ambiguous citation', () => {
    const before = readFileSync(join(process.cwd(), spec('ambiguous')), 'utf8');
    const after = onACopy('ambiguous', path => run(path, '--fix'));

    expect(after).toBe(before);
  });

  it('refuses to write a name that would break the markdown label', () => {
    const before = readFileSync(join(process.cwd(), spec('bracket')), 'utf8');
    const after = onACopy('bracket', path => run(path, '--fix'));

    expect(after).toBe(before);
  });

  it('reports a citation of a test declared with xit, which never runs', () => {
    expect(run(spec('skipped')).stderr).toContain('which is skipped and validates nothing');
  });

  it('reports a citation of a test declared with .skip the same way', () => {
    expect(run(spec('skipped-dot'))).toMatchObject({status: 1});
  });

  it('reports a root-relative href, which the drift check would never read', () => {
    expect(run(spec('rooted')).stderr).toContain('must be relative and start with ../');
  });

  it('reports an href starting ./, which this gate would otherwise have skipped', () => {
    expect(run(spec('dotted'))).toMatchObject({status: 1});
  });
});

#!/usr/bin/env node
// Runs exactly one test for the Lore test-command interface. The selector is
// "<repo-relative-file>::<full test name>" as emitted by lore-list-tests.mjs.
// Jest's -t flag is a regex matched against the full name, so the name is
// escaped and anchored - a name containing (parens) or {500} must match
// literally - and the file is passed with --runTestsByPath, which takes a path
// rather than the regex a bare positional argument would be.
// A selector that matches nothing is a failure, never a silently green run of
// an empty suite.
import {execFileSync} from 'node:child_process';
import {readFileSync, rmSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {join} from 'node:path';
import process from 'node:process';

const selector = process.argv[2];

if (!selector || !selector.includes('::')) {
  process.stderr.write('usage: lore-run-test.mjs "<file>::<full test name>"\n');
  process.exit(2);
}

const separator = selector.indexOf('::');
const file = selector.slice(0, separator);
const name = selector.slice(separator + 2);
const escaped = name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

const reportFile = join(tmpdir(), `hal-engine-jest-run-${process.pid}.json`);

let runFailed = false;

try {
  execFileSync(
    'npx',
    [
      'jest',
      '--runTestsByPath',
      file,
      '-t',
      `^${escaped}$`,
      '--json',
      `--outputFile=${reportFile}`,
      '--coverage',
      '--coverageReporters=lcov',
    ],
    {
      cwd: process.cwd(),
      stdio: ['ignore', 'inherit', 'inherit'],
      // The suite runs as ESM; jest needs the flag in every spawn, not just npm test.
      env: {...process.env, NODE_OPTIONS: `${process.env.NODE_OPTIONS ?? ''} --experimental-vm-modules`.trim()},
    }
  );
} catch {
  runFailed = true;
}

let report;

try {
  report = JSON.parse(readFileSync(reportFile, 'utf8'));
} catch (error) {
  process.stderr.write(`jest produced no readable report at ${reportFile}: ${error.message}\n`);
  process.exit(1);
} finally {
  rmSync(reportFile, {force: true});
}

// Every test in the file that -t did not select is reported as pending, so the
// count that matters is the ones actually executed.
const ran = report.numTotalTests - (report.numPendingTests ?? 0);

if (ran === 0) {
  process.stderr.write(`selector matched no test: ${selector}\n`);
  process.exit(1);
}

process.exit(runFailed || report.numFailedTests > 0 ? 1 : 0);
// Local counterpart of the Lore spec-coverage job that consumes these links: a `([validated by](...))`
// link only counts when it sits in its statement's trailing parenthetical, so a
// link anywhere else is reported here rather than silently dropped there.
// Segmentation and link parsing come from the published spec domain
// of @re-cinq/eslint-plugin-re-lint (AGENTS.md § Spec Test Links).

import { readFileSync, readdirSync } from "node:fs";
import { join, relative, resolve } from "node:path";
import process from "node:process";
import { findMisplacedCoverageLinks } from "@re-cinq/eslint-plugin-re-lint/spec/spec-link-parser.js";
import { segmentStatements } from "@re-cinq/eslint-plugin-re-lint/spec/spec-segment.js";
import { root } from "./lib/repo-root.mjs";

const USAGE =
  "usage: check-spec-links.mjs [--json] [spec-path ...]\n" +
  "spec paths resolve against the repo root, not the working directory; an absolute path is taken as given";

const args = process.argv.slice(2);
const flags = args.filter((arg) => arg.startsWith("--"));
const specArgs = args.filter((arg) => !arg.startsWith("--"));

for (const flag of flags) {
  if (flag === "--json") {
    continue;
  }
  process.stderr.write(`${USAGE}\n`);
  process.exit(2);
}

const asJson = flags.includes("--json");

const discoverSpecs = () => {
  const specsDir = join(root, "specs");
  const slugs = readdirSync(specsDir, { withFileTypes: true })
    .filter((entry) => entry.isDirectory())
    .map((entry) => entry.name)
    .sort();

  return [...slugs.map((slug) => `specs/${slug}/spec.md`), ".specify/spec.md"];
};

const specPaths =
  specArgs.length > 0
    ? specArgs.map((path) => relative(root, resolve(root, path)))
    : discoverSpecs();

const readSpec = (specPath) => {
  try {
    return readFileSync(join(root, specPath), "utf8");
  } catch (error) {
    process.stderr.write(`cannot read spec ${specPath}: ${error.message}\n`);
    process.exit(2);
  }
};

const findings = [];
const specsWithFindings = new Set();
let statementsScanned = 0;

for (const specPath of specPaths) {
  const content = readSpec(specPath);

  for (const statement of segmentStatements(content)) {
    statementsScanned += 1;

    for (const link of findMisplacedCoverageLinks(statement.text)) {
      findings.push({
        spec: specPath,
        line: statement.line ?? null,
        path: link.path,
        anchorLine: link.line,
        label: link.label,
        statement: statement.text,
      });
      specsWithFindings.add(specPath);
    }
  }
}

const reportLines = () => {
  const lines = findings.map((finding) => {
    const anchor = finding.anchorLine === null ? "" : `#L${finding.anchorLine}`;
    const line = finding.line ?? "?";

    return `${finding.spec}:${line}: ${finding.path}${anchor} cited outside the statement's trailing parenthetical`;
  });

  lines.push(
    `misplaced: ${findings.length} across ${specsWithFindings.size} specs (${statementsScanned} statements scanned)`
  );

  return lines;
};

// process.exitCode, not process.exit: exiting truncates a large stdout write
// to a pipe.
process.exitCode = findings.length > 0 ? 1 : 0;
process.stdout.write(
  asJson ? `${JSON.stringify(findings, null, 2)}\n` : `${reportLines().join("\n")}\n`
);
